    addDomainNameserver(id: number, domainNameserverPostRequest: DomainNameserverPostRequest, options?: RequestOptions): Promise<TextResponse>,

    cancelDomain(id: number, options?: RequestOptions): Promise<CancelDomain200Response>,

    deleteDomainDnssec(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    deleteDomainNameserver(id: number, index: number, options?: RequestOptions): Promise<TextResponse>,

    getDomainContact(id: number, options?: RequestOptions): Promise<DomainContactDetails>,

    getDomainDnssec(id: number, options?: RequestOptions): Promise<DomainDnssecRecords>,

    getDomainInfo(id: number, options?: RequestOptions): Promise<Domain>,

    getDomainInvoices(id: number, options?: RequestOptions): Promise<ChargeInvoiceRows>,

    getDomainLookup(name: string, options?: RequestOptions): Promise<DomainLookupResponse>,

    getDomainNameservers(id: number, options?: RequestOptions): Promise<DomainNameserverGetResponse>,

    getDomainRenewal(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    getDomainSearch(name: string, options?: RequestOptions): Promise<DomainSearchResponse>,

    getDomainTransfer(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    getDomainWhoisPrivacy(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    getDomainsList(options?: RequestOptions): Promise<Array<DomainRow>>,

    getDomainsWelcomeEmail(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    getNewDomain(options?: RequestOptions): Promise<DomainOrder>,

    patchDomains(domainOrderRequest: DomainOrderRequest, options?: RequestOptions): Promise<Response>,

    postDomainRenewal(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    postDomainSearch(name: string, options?: RequestOptions): Promise<Response>,

    postDomainTransfer(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    putDomains(domainOrderRequest: DomainOrderRequest, options?: RequestOptions): Promise<Response>,

    updateDomainContact(id: number, domainContactDetails: DomainContactDetails, options?: RequestOptions): Promise<SuccessTextResponse>,

    updateDomainInfo(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

