export type WebhostingApiType = { 
    addWebsite(websiteOrderPostRequest: WebsiteOrderPostRequest, options?: RequestOptions): Promise<ServiceOrderPostResponse>,

    getNewWebsite(options?: RequestOptions): Promise<WebsitesOrder>,

    getWebsiteBuyIp(id: number, options?: RequestOptions): Promise<GetWebsiteBuyIp200Response>,

    getWebsiteInfo(id: number, options?: RequestOptions): Promise<Website>,

    getWebsiteInvoices(id: number, options?: RequestOptions): Promise<ChargeInvoiceRows>,

    getWebsiteList(options?: RequestOptions): Promise<Array<WebsiteRow>>,

    getWebsitesBackups(id: number, options?: RequestOptions): Promise<WebsiteBackups>,

    getWebsitesLogin(id: number, options?: RequestOptions): Promise<WebsiteLoginResponse>,

    getWebsitesWelcomeEmail(id: number, options?: RequestOptions): Promise<SuccessTextResponse>,

    gettWebsiteReverseDns(id: number, options?: RequestOptions): Promise<ReverseDnsEntries>,

    postWebsiteBuyIp(id: number, postWebsiteBuyIpRequest: PostWebsiteBuyIpRequest, options?: RequestOptions): Promise<PostWebsiteBuyIp200Response>,

    postWebsiteMigration(id: number, postWebsiteMigrationRequest: PostWebsiteMigrationRequest, options?: RequestOptions): Promise<PostWebsiteMigration200Response>,

    postWebsitesReverseDns(id: number, reverseDnsEntries: ReverseDnsEntries, options?: RequestOptions): Promise<TextResponse>,

    putWebsites(websiteOrderPutRequest: WebsiteOrderPutRequest, options?: RequestOptions): Promise<Response>,

    updateWebsiteInfo(id: string, options?: RequestOptions): Promise<SuccessTextResponse>,

    webhostingCancel(id: string, options?: RequestOptions): Promise<WebhostingCancel200Response>,
}

